import{_ as r,o as a,c as n,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/unterricht-kataloge/kataloge-fahrschuelerarten.png",m=JSON.parse('{"title":"Fahrschülerarten im Katalog vorbereiten","description":"","frontmatter":{"title":"Fahrschülerarten im Katalog vorbereiten","source_pageid":376,"source_revision":5420},"headers":[],"relativePath":"schild3/unterricht-kataloge/fahrschueler-arten-allgemeine-kataloge.md","filePath":"schild3/unterricht-kataloge/fahrschueler-arten-allgemeine-kataloge.md"}'),i={name:"schild3/unterricht-kataloge/fahrschueler-arten-allgemeine-kataloge.md"};function s(o,e,h,d,g,c){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="fahrschulerarten-im-katalog-vorbereiten" tabindex="-1">Fahrschülerarten im Katalog vorbereiten <a class="header-anchor" href="#fahrschulerarten-im-katalog-vorbereiten" aria-label="Permalink to &quot;Fahrschülerarten im Katalog vorbereiten&quot;">​</a></h1><p>Legen Sie die benötigten Fahrschülerarten an. Diese können Sie in Individualdaten I zuordnen und anschließend für die Schülerauswahl verwenden.</p><p><a href="/bilder/unterricht-kataloge/kataloge-fahrschuelerarten.png"><img src="'+l+'" alt="Erstellen Sie den Katalog mit bei Ihnen anfallenden Fahrschülerarten." loading="lazy"></a></p><p><em>Erstellen Sie den Katalog mit bei Ihnen anfallenden Fahrschülerarten.</em></p><p>Unter <strong>Kataloge ➜ Fahrschülerarten</strong> hinterlegen Sie die an Ihrer Schule benötigten Arten der Schülerbeförderung, etwa mit öffentlichen Verkehrsmitteln oder nach besonderen Beförderungsregelungen.</p><p>Wie in Katalogen üblichen sind Einträge über das &quot;<strong>+</strong>&quot; und &quot;<strong>-</strong>&quot; zu setzen beziehungsweise zu entfernen.</p><p>Der Eintrag wird dann in den <em>Individualdaten I</em> unter <em>Zusatzdaten</em> gesetzt und es kann über den <em>Filter I</em> auf diese Fahrschülerarten gefiltert werden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Fahrsch%C3%BCler-Arten_(Allgemeine_Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5420.</p>',9)])])}const p=r(i,[["render",s]]);export{m as __pageData,p as default};
